import Foundation

/// Reads the release asset index generated by にゃっとランドforX and serves
/// the same byte slices its Manifest V3 service worker would return.
@MainActor
final class PackedAssetStore {
    private struct Entry: Decodable {
        let pack: String
        let offset: Int
        let length: Int
        let mime: String
    }

    private let root: URL
    private let index: [String: Entry]
    private var packCache: [String: Data] = [:]

    init(root: URL) throws {
        self.root = root.standardizedFileURL
        let workerURL = root.appendingPathComponent("xff-assets.js")
        let source = try String(contentsOf: workerURL, encoding: .utf8)
        self.index = try Self.parseIndex(from: source)
    }

    func base64Assets(for requestedPaths: [String]) throws -> [String: String] {
        guard !requestedPaths.isEmpty, requestedPaths.count <= 128 else {
            throw PackedAssetError.invalidRequest
        }

        var result: [String: String] = [:]
        result.reserveCapacity(requestedPaths.count)

        for path in Set(requestedPaths) {
            guard let entry = index[path] else { throw PackedAssetError.unknownAsset(path) }
            let pack = try packData(for: entry.pack)
            guard entry.offset >= 0,
                  entry.length > 0,
                  entry.offset <= pack.count,
                  entry.offset + entry.length <= pack.count else {
                throw PackedAssetError.invalidSlice(path)
            }
            result[path] = pack.subdata(in: entry.offset..<(entry.offset + entry.length)).base64EncodedString()
        }
        return result
    }

    private func packData(for relativePath: String) throws -> Data {
        if let cached = packCache[relativePath] { return cached }
        guard !relativePath.hasPrefix("/"), !relativePath.contains("..") else {
            throw PackedAssetError.invalidPackPath(relativePath)
        }
        let url = root.appendingPathComponent(relativePath).standardizedFileURL
        guard url.path.hasPrefix(root.path + "/") else {
            throw PackedAssetError.invalidPackPath(relativePath)
        }
        let data = try Data(contentsOf: url, options: [.mappedIfSafe])
        packCache[relativePath] = data
        return data
    }

    private static func parseIndex(from workerSource: String) throws -> [String: Entry] {
        let prefix = "const XFF_ASSET_INDEX = Object.freeze("
        guard let prefixRange = workerSource.range(of: prefix) else {
            throw PackedAssetError.indexNotFound
        }
        let rest = workerSource[prefixRange.upperBound...]
        guard let suffixRange = rest.range(of: ");\nconst xffPackPromises") else {
            throw PackedAssetError.indexNotFound
        }
        let json = String(rest[..<suffixRange.lowerBound])
        guard let data = json.data(using: .utf8) else { throw PackedAssetError.indexNotFound }
        let decoded = try JSONDecoder().decode([String: Entry].self, from: data)
        guard !decoded.isEmpty else { throw PackedAssetError.indexNotFound }
        return decoded
    }
}

enum PackedAssetError: LocalizedError {
    case invalidRequest
    case indexNotFound
    case unknownAsset(String)
    case invalidPackPath(String)
    case invalidSlice(String)

    var errorDescription: String? {
        switch self {
        case .invalidRequest: "画像アセット要求が不正です。"
        case .indexNotFound: "拡張機能の画像インデックスを読み込めません。"
        case .unknownAsset(let path): "未登録の画像アセットです: \(path)"
        case .invalidPackPath(let path): "不正なアセットpack pathです: \(path)"
        case .invalidSlice(let path): "アセットpack内の範囲が不正です: \(path)"
        }
    }
}
